import { tv } from "tailwind-variants";

/*
Slots and their data-attributes and css variables:

trigger: data-popup-open/data-disabled
backdrop: data-open/data-closed/data-starting-style/data-ending-style
viewport: data-open/data-closed/data-nested/data-nested-dialog-open/data-starting-style/data-ending-style
popup: data-open/data-closed/data-nested/data-nested-dialog-open/data-starting-style/data-ending-style; --nested-dialogs
close: data-disabled
*/

const alertDialog = tv({
  slots: {
    trigger: "",
    portal: "",
    backdrop: [
      "fixed inset-0 min-h-dvh bg-black/20 backdrop-blur-xs transition-all duration-150 ease-default",
      "data-ending-style:opacity-0 data-starting-style:opacity-0",
      "supports-[-webkit-touch-callout:none]:absolute",
      "dark:bg-black/50",
    ],
    viewport: "",
    popup: [
      "fixed top-1/2 left-1/2 flex w-md max-w-[calc(100vw-3rem)] -translate-x-1/2 -translate-y-1/2 flex-col rounded-lg border border-border bg-popover text-popover-foreground shadow-lg transition-[scale,opacity] duration-300 ease-default outline-none",
      "data-ending-style:scale-95 data-ending-style:opacity-0",
      "data-starting-style:scale-95 data-starting-style:opacity-0",
    ],
    header: "flex flex-col gap-1.5 p-4",
    title: "text-base leading-none font-semibold text-foreground",
    description: "text-sm text-muted-foreground",
    footer: "flex flex-wrap items-center justify-end gap-2 p-4",
    close: "",
  },
});

export { alertDialog };

"use client";

import { mergeProps, useDirection, useRender } from "@base-ui/react";
import { AlertDialog as BaseAlertDialog } from "@base-ui/react/alert-dialog";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { alertDialog } from "./alert-dialog.style";

type AlertDialogHandle = ReturnType<typeof BaseAlertDialog.createHandle>;
const createAlertDialogHandle = BaseAlertDialog.createHandle;

function AlertDialog(props: BaseAlertDialog.Root.Props) {
  return <BaseAlertDialog.Root {...props} />;
}

function AlertDialogTrigger({
  className,
  ...props
}: BaseAlertDialog.Trigger.Props) {
  return (
    <BaseAlertDialog.Trigger
      data-slot="alert-dialog-trigger"
      className={mergeSlotClassName(alertDialog().trigger, className)}
      {...props}
    />
  );
}

function AlertDialogPortal({
  className,
  ...props
}: BaseAlertDialog.Portal.Props) {
  return (
    <BaseAlertDialog.Portal
      data-slot="alert-dialog-portal"
      className={mergeSlotClassName(alertDialog().portal, className)}
      {...props}
    />
  );
}

function AlertDialogBackdrop({
  className,
  ...props
}: BaseAlertDialog.Backdrop.Props) {
  return (
    <BaseAlertDialog.Backdrop
      data-slot="alert-dialog-backdrop"
      className={mergeSlotClassName(alertDialog().backdrop, className)}
      {...props}
    />
  );
}

function AlertDialogViewport({
  className,
  ...props
}: BaseAlertDialog.Viewport.Props) {
  return (
    <BaseAlertDialog.Viewport
      data-slot="alert-dialog-viewport"
      className={mergeSlotClassName(alertDialog().viewport, className)}
      {...props}
    />
  );
}

function AlertDialogPopup({
  className,
  ...props
}: BaseAlertDialog.Popup.Props) {
  const direction = useDirection();

  return (
    <BaseAlertDialog.Popup
      data-slot="alert-dialog-popup"
      className={mergeSlotClassName(alertDialog().popup, className)}
      {...props}
      dir={direction}
    />
  );
}

function AlertDialogHeader({
  className,
  render,
  ...props
}: useRender.ComponentProps<"div">) {
  const header = useRender({
    defaultTagName: "div",
    props: {
      ...mergeProps<"div">(
        { className: alertDialog().header({ className }) },
        props,
      ),
      "data-slot": "alert-dialog-header",
    },
    render,
  });

  return header;
}

function AlertDialogTitle({
  className,
  ...props
}: BaseAlertDialog.Title.Props) {
  return (
    <BaseAlertDialog.Title
      data-slot="alert-dialog-title"
      className={mergeSlotClassName(alertDialog().title, className)}
      {...props}
    />
  );
}

function AlertDialogDescription({
  className,
  ...props
}: BaseAlertDialog.Description.Props) {
  return (
    <BaseAlertDialog.Description
      data-slot="alert-dialog-description"
      className={mergeSlotClassName(alertDialog().description, className)}
      {...props}
    />
  );
}

function AlertDialogFooter({
  className,
  render,
  ...props
}: useRender.ComponentProps<"div">) {
  const footer = useRender({
    defaultTagName: "div",
    props: {
      ...mergeProps<"div">(
        { className: alertDialog().footer({ className }) },
        props,
      ),
      "data-slot": "alert-dialog-footer",
    },
    render,
  });

  return footer;
}

function AlertDialogClose({
  className,
  ...props
}: BaseAlertDialog.Close.Props) {
  return (
    <BaseAlertDialog.Close
      data-slot="alert-dialog-close"
      className={mergeSlotClassName(alertDialog().close, className)}
      {...props}
    />
  );
}

export {
  createAlertDialogHandle,
  AlertDialog,
  AlertDialogTrigger,
  AlertDialogPortal,
  AlertDialogBackdrop,
  AlertDialogViewport,
  AlertDialogPopup,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogClose,
};
export type { AlertDialogHandle };
